var PRE_COMBAT_NARRATIONS={forest:['Galhos estalando! Algo grande se move entre as \u00e1rvores, e voc\u00ea sente o ch\u00e3o tremer sob seus p\u00e9s.','Um rosnado baixo ecoa entre o arvoredo. Olhos brilhantes surgem na escurid\u00e3o — a ca\u00e7a come\u00e7ou.','As folhas se agitam violentamente. Uma presen\u00e7a hostil emerge das sombras da floresta.',],plains:['O vento muda de dire\u00e7\u00e3o. Ao longe, uma silhueta se aproxima com passos decididos.','A grama alta se abre de repente. Algo estava esperando por voc\u00ea.','O sil\u00eancio das plan\u00edcies \u00e9 quebrado por um grito de guerra.',],cave:['Pedras caem do teto. Nos t\u00faneis escuros, algo respira pesadamente.','A tocha vacila. Uma sombra se move na parede — n\u00e3o \u00e9 a sua.','O eco dos seus passos \u00e9 interrompido por um sibilo ameac\u0327ador.',],swamp:['Bolhas est\u00e3o surgindo na lama. Algo emerge lentamente das \u00e1guas turvas.','O ch\u00e3o treme sob seus p\u00e9s. Uma criatura do p\u00e2ntano despertou.','N\u00e9voa t\u00f3xica se adensa. Atrav\u00e9s dela, olhos \u00e2mbar brilham com fome.',],desert:['A areia se agita em esp\u00edrais. Algo sob a duna se desloca na sua dire\u00e7\u00e3o com velocidade assustadora.','O calor distorce o ar, mas n\u00e3o \u00e9 uma miragem — a criatura \u00e9 real e letal.',],mountain:['Pedras rolam morro abaixo. Algo se move entre os penhascos, circundando voc\u00ea.','Um rugido ecoa pelas montanhas. A criatura salta de uma sali\u00eancia rochosa.',],snow:['A neve se agita. Passos pesados se aproximam atrav\u00e9s da nevasca.','O frio se intensifica. Uma presen\u00e7a ancestral emerge do gelo.',],volcanic:['Lava borbulha. Das fissuras incandescentes, algo se ergue envolvido em chamas.','O calor se torna insuport\u00e1vel. Uma criatura de fogo bloqueia seu caminho.',],graveyard:['L\u00e1pides tremem. A terra se abre e m\u00e3os esquel\u00e9ticas emergem do solo.','O ar gela. Uma presen\u00e7a sobrenatural materializa diante de voc\u00ea.',],};function _getPreCombatNarration(biome,enemyName){var pool=PRE_COMBAT_NARRATIONS[biome]||PRE_COMBAT_NARRATIONS.forest;return pool[Math.floor(Math.random()*pool.length)];}
