var _BIOME_FLAVOR={cave:['Gotas d\'agua ecoam no escuro...','O ar e umido e frio. Musgo cobre as pedras.','Riscos antigos marcam a parede da caverna.','Um cheiro de terra molhada permeia o tunel.','Estalagmites brilham fracamente com minerais.','Ossos pequenos se espalham pelo chao rochoso.','O eco de seus passos viaja longe na escuridao.','Raizes grossas perfuram o teto da caverna.',],graveyard:['Lapides desgastadas se inclinam no escuro.','Uma brisa gelada carrega sussurros indistintos.','Teias de aranha cobrem um velho candelabro.','O chao de pedra esta marcado por runas apagadas.','Um odor de mofo e incenso velho paira no ar.','Ossos antigos descansam em nichos na parede.','A escuridao aqui parece mais densa que o normal.','Velas derretidas formam estalactites de cera.',],volcanic:['O calor e quase insuportavel nesta area.','Fissuras no chao emitem um brilho alaranjado.','O ar treme com ondas de calor intenso.','Cristais negros de obsidiana brilham fracamente.','Cinzas vulcanicas cobrem tudo como neve escura.','O chao vibra com um tremor distante.',],mountain:['O vento uiva pelas fendas na rocha.','Neve antiga se acumula nos cantos sombrios.','Marcas de garras enormes riscam a pedra.','O ar rarefeito dificulta a respiracao.','Cristais de gelo decoram as paredes de granito.','Pedras soltas rangem sob seus pes.',],swamp:['Bolhas sobem da lama escura com um plop.','Raizes retorcidas formam arcos naturais.','O ar e denso com o cheiro de decomposicao.','Insetos luminescentes piscam entre os juncos.','A lama suga seus passos com avidez.','Vapores esverdeados sobem do charco proximo.',],forest:['Raios de luz filtram pela copa das arvores.','Cogumelos brilhantes crescem em um tronco caido.','Pegadas de animais marcam a trilha a frente.','Folhas secas estaliam sob seus passos.','Um riacho murmura suavemente ao longe.','O canto de passaros ecoa entre as arvores.',],desert:['O sol escaldante reflete na areia clara.','Dunas de areia fina se movem com o vento.','Ossos branqueados pelo sol marcam uma antiga trilha.','O calor cria miragens tremeluzentes no horizonte.',],};var _flavorCooldown=0;var _FLAVOR_CHANCE=0.12;var _FLAVOR_COOLDOWN_STEPS=6;function checkFlavorText(col,row){if(_flavorCooldown>0){_flavorCooldown--;return;}
const tile=S.grid[row]&&S.grid[row][col];if(!tile||tile==='#'||tile==='D'||tile==='@'||tile==='E')return;if(Math.random()>_FLAVOR_CHANCE)return;const biome=S.biome||'cave';const pool=_BIOME_FLAVOR[biome]||_BIOME_FLAVOR['cave'];if(!pool||pool.length===0)return;const idx=(col*7+row*13+(S._stepCount||0))%pool.length;const text=pool[idx];showTerrainToast(text,'flavor');_flavorCooldown=_FLAVOR_COOLDOWN_STEPS;}